/**
 * Test flow for sendSms action
 * Demonstrates sending an SMS message
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testSendSms = Flow(
    {
        $id: Now.ID['test_send_sms_flow'],
        name: 'Test Send SMS',
        description: 'Tests the sendSms core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_send_sms_trigger'] },
        {
            table: 'incident',
            condition: 'priority=1',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.sendSms,
            { $id: Now.ID['test_send_sms_action'] },
            {
                recipients: '+1234567890',
                message: `Critical incident ${wfa.dataPill(_params.trigger.current.number, 'integer')} created`,
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_send_sms_log'] },
            {
                log_level: 'info',
                log_message: `sendSms outputs: email=${wfa.dataPill(result.email, 'reference')}`,
            }
        )
    }
)
